#include <iostream>
#include <unordered_map>
#include <utility>
#include <algorithm>

using namespace std;

long long compute(int n, int h, unordered_map<pair<int, int>, long long, hash<pair<int, int>>> &cache) {
    pair<int, int> key = make_pair(n, h);
    if (cache.find(key) == cache.end()) {
        if (n == 0) {
            cache[key] = 1;
        } else {
            long long sum_value = 0;
            if (h != 0) {
                for (int i = 0; i < n; ++i) {
                    sum_value += compute(i, h - 1, cache) * compute(n - 1 - i, h - 1, cache);
                }
                cache[key] = sum_value;
            } else {
                cache[key] = 0;
            }
        }
    }
    return cache[key];
}

struct pair_hash {
    size_t operator()(const pair<int, int>& p) const {
        return hash<int>()(p.first) ^ (hash<int>()(p.second) << 1);
    }
};

int main() {
    int n, h;
    cin >> n >> h;
    unordered_map<pair<int, int>, long long, pair_hash> cache;
    long long result = compute(n, n, cache) - compute(n, max(0, h - 1), cache);
    cout << result << endl;
    return 0;
}

